export type MessageKey = keyof typeof messages.en
export type MessageOverrides = Partial<Record<MessageKey, string>>

export function createTranslator(
  locale: TrajectoryLocale,
  overrides: MessageOverrides = {},
): (key: MessageKey, values?: Readonly<Record<string, string | number>>) => string {
  const dictionary = messages[locale]
  return (key, values = {}) => {
    const template = overrides[key] ?? dictionary[key] ?? messages.en[key]
    return Object.entries(values).reduce(
      (result, [name, value]) => result.replaceAll(`{${name}}`, String(value)),
      template,
    )
  }
}
